style.css:
/* Nord Colors */
:root {
  -nord0: #2E3440;
  -nord1: #3B4252;
  -nord2: #434C5E;
  -nord3: #4C566A; /* Main page background */
  -nord4: #D8DEE9;
  -nord5: #E5E9F0;
  -nord6: #ECEFF4; /* Main text color */
  -nord7: #8FBCBB;
  -nord8: #88C0D0;
  -nord9: #81A1C1;
  -nord10: #5E81AC;
  -nord11: #BF616A;
  -nord12: #D08770;
  -nord13: #EBCB8B;
  -nord14: #A3BE8C;
  -nord15: #B48EAD;
}

/* Body and Background */
body {
  background-color: var(-nord3); /* Main background */
  color: var(-nord6); /* Main text color */
  font-family: 'Arial', sans-serif;
}
